#!/usr/bin/env bash
set -euo pipefail

PROJECT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$PROJECT_DIR"
PORT="${PORT:-3000}"
STATIC_DIR="$PROJECT_DIR/dist"

run() { /usr/bin/time -p "$@"; }

if [[ -f "$PROJECT_DIR/package.json" ]]; then
  if [[ -f "$PROJECT_DIR/package-lock.json" ]]; then
    run npm ci --no-audit --no-fund
  else
    run npm install --no-audit --no-fund
  fi
  run npm run build
  [[ -f "$STATIC_DIR/index.html" ]] || { echo "Build did not create $STATIC_DIR/index.html" >&2; exit 1; }
elif [[ ! -f "$STATIC_DIR/index.html" ]]; then
  run mkdir -p "$STATIC_DIR"
  run cat > "$STATIC_DIR/index.html" <<'HTML'
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="theme-color" content="#071b19"><title>River Room — Texas Hold'em</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&family=Playfair+Display:wght@600;700&display=swap');
:root{color-scheme:dark;--felt:#12473a;--felt2:#0e3c32;--gold:#e5bc70;--muted:#91a99f;--cream:#f7f3e9;--panel:#102622;--line:#244038;--red:#cf5a52}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 50% 0%,#18352e 0,#091a17 48%,#071310 100%);color:var(--cream);font-family:'DM Sans',sans-serif}.shell{max-width:1220px;margin:auto;padding:24px 34px 32px}.topbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:25px}.brand{display:flex;gap:12px;align-items:center}.brand-icon{width:37px;height:37px;border:1px solid #6d624b;border-radius:50%;display:grid;place-items:center;color:var(--gold);font-size:19px}.brand-name{font-family:'Playfair Display',serif;font-size:17px;letter-spacing:.04em}.brand-sub{display:block;color:#80958b;text-transform:uppercase;letter-spacing:.18em;font:9px 'DM Mono',monospace;margin-top:3px}.top-actions{display:flex;gap:10px;align-items:center}.pill,.icon-btn{border:1px solid #34463e;background:#10211d;color:#c5d0c7;border-radius:20px;padding:8px 13px;font-size:11px}.pill span{color:var(--gold);margin-right:5px}.icon-btn{width:34px;height:34px;padding:0;border-radius:50%;font-size:15px;cursor:pointer}.layout{display:grid;grid-template-columns:minmax(0,1fr) 248px;gap:18px}.game-column{min-width:0}.table-head{display:flex;justify-content:space-between;align-items:flex-end;margin:0 10px 12px}.eyebrow{font:10px 'DM Mono',monospace;text-transform:uppercase;letter-spacing:.16em;color:var(--gold)}h1{font:600 25px 'Playfair Display',serif;margin:5px 0 0}.table-meta{font:10px 'DM Mono',monospace;color:#9bb0a6}.poker-table{height:468px;position:relative;border:1px solid #47755c;border-radius:48% / 49%;background:radial-gradient(ellipse at 50% 45%,#1b654e 0,#15513f 49%,#104535 75%,#0d382e 100%);box-shadow:inset 0 0 0 8px #18352d,inset 0 0 0 10px #52724e,0 22px 65px #0008;overflow:visible}.poker-table:before{content:'';position:absolute;inset:23px;border:1px solid #78a07a55;border-radius:48% / 49%;pointer-events:none}.table-ornament{position:absolute;left:50%;top:19%;transform:translateX(-50%);font:10px 'DM Mono',monospace;letter-spacing:.28em;color:#e5d6a542;text-transform:uppercase}.seats{position:absolute;inset:0}.seat{position:absolute;min-width:126px;text-align:center;z-index:2}.seat[data-seat="0"]{left:50%;bottom:-27px;transform:translateX(-50%)}.seat[data-seat="1"]{left:3%;top:50%;transform:translateY(-50%)}.seat[data-seat="2"]{left:50%;top:-24px;transform:translateX(-50%)}.seat[data-seat="3"]{right:3%;top:50%;transform:translateY(-50%)}.player-info{display:inline-flex;align-items:center;gap:7px;background:#10231f;border:1px solid #536a56;border-radius:22px;padding:6px 11px 6px 6px;box-shadow:0 5px 14px #0005;white-space:nowrap}.avatar{width:29px;height:29px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(145deg,#d9bd81,#907447);color:#18231c;font-weight:800;font-size:12px}.seat[data-seat="0"] .avatar{background:linear-gradient(145deg,#e1c889,#96794d)}.player-name{text-align:left;font-size:10px;font-weight:700}.player-stack{font:9px 'DM Mono',monospace;color:var(--gold);margin-top:2px}.dealer-chip{position:absolute;top:-3px;right:-5px;width:17px;height:17px;background:#f3e8c6;color:#4a3920;border-radius:50%;font:9px 'DM Mono',monospace;display:grid;place-items:center;border:2px solid #af945e}.status-tag{position:absolute;left:50%;top:100%;margin-top:5px;transform:translateX(-50%);font:9px 'DM Mono',monospace;color:#f2d594;white-space:nowrap;text-shadow:0 1px 5px #000}.hole-cards{display:flex;justify-content:center;gap:4px;margin-top:7px;min-height:51px}.playing-card{width:35px;height:49px;border-radius:5px;background:var(--cream);color:#18211d;box-shadow:0 2px 6px #0007;position:relative;display:flex;align-items:center;justify-content:center;font:700 15px 'DM Sans',sans-serif}.playing-card.red{color:#bc4545}.playing-card .corner{position:absolute;left:4px;top:3px;font:700 8px/9px 'DM Sans',sans-serif;text-align:center}.playing-card.back{background:repeating-linear-gradient(45deg,#244c43 0 3px,#173b34 3px 6px);border:1px solid #93a47e;color:#b1bf9c;font-size:15px}.playing-card.back:after{content:'';position:absolute;inset:4px;border:1px solid #93a47e88;border-radius:3px}.community{position:absolute;left:50%;top:47%;transform:translate(-50%,-50%);display:flex;align-items:center;gap:9px;min-height:80px;z-index:1}.community .playing-card{width:49px;height:68px;font-size:21px;border-radius:7px}.community .playing-card .corner{font-size:10px;line-height:11px;left:5px;top:5px}.pot-box{position:absolute;left:50%;top:29%;transform:translateX(-50%);text-align:center;z-index:1}.pot-label{font:9px 'DM Mono',monospace;letter-spacing:.16em;text-transform:uppercase;color:#b8d2b6}.pot-value{font:600 18px 'DM Mono',monospace;color:#f3d48f;margin-top:3px;text-shadow:0 2px 12px #14271c}.stage-badge{position:absolute;left:50%;top:71%;transform:translateX(-50%);font:9px 'DM Mono',monospace;color:#c0d0bc;text-transform:uppercase;letter-spacing:.15em;white-space:nowrap}.notice{position:absolute;left:50%;top:82%;transform:translateX(-50%);font-size:11px;color:#fff4d6;text-shadow:0 2px 8px #000;white-space:nowrap;text-align:center}.seat.active .player-info{border-color:var(--gold);box-shadow:0 0 0 2px #e5bc7033,0 5px 14px #0005}.seat.folded{opacity:.42}.seat.winner .player-info{border-color:#e8c875;box-shadow:0 0 18px #f4d57b66}.action-bar{display:flex;gap:8px;align-items:center;justify-content:center;margin:43px auto 0}.action-btn{height:42px;min-width:103px;padding:0 18px;border:1px solid #415d4e;border-radius:6px;background:#152a24;color:#e7e5d6;font:600 11px 'DM Sans',sans-serif;cursor:pointer;transition:.15s}.action-btn:hover:not(:disabled){transform:translateY(-2px);border-color:#bb9c5e}.action-btn:disabled{opacity:.38;cursor:not-allowed}.action-btn.primary{background:var(--gold);color:#1b251e;border-color:var(--gold);font-weight:800}.action-btn.primary:hover:not(:disabled){background:#f2cc82}.action-btn.fold{color:#df9d94}.raise-wrap{display:flex;gap:5px}.raise-wrap .action-btn{min-width:115px}.hint{min-height:20px;margin-top:10px;text-align:center;color:#83988e;font-size:10px}.sidebar{border:1px solid var(--line);border-radius:8px;background:linear-gradient(180deg,#112722,#0e201c);padding:17px 15px;min-height:100%}.side-title{font:10px 'DM Mono',monospace;text-transform:uppercase;letter-spacing:.16em;color:#bca16b;margin:2px 0 16px}.stat-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.stat{background:#0b1c18;border:1px solid #1e3830;border-radius:5px;padding:10px}.stat-label{color:#80958a;font-size:9px}.stat-value{font:13px 'DM Mono',monospace;color:#f1e7ca;margin-top:5px}.divider{height:1px;background:#263a32;margin:17px 0}.history-head{display:flex;justify-content:space-between;align-items:center}.history-head button{border:0;background:none;color:#71877c;font-size:10px;cursor:pointer}.history{display:flex;flex-direction:column;gap:11px}.history-item{display:flex;gap:9px;font-size:10px;color:#b2beb3;line-height:1.45}.history-dot{flex:none;margin-top:4px;width:6px;height:6px;border-radius:50%;background:#c9a868}.history-item small{display:block;color:#73877d;font:9px 'DM Mono',monospace;margin-top:3px}.empty-history{color:#74877d;font-size:10px;line-height:1.6}.guide{margin-top:17px;padding:12px;background:#0b1b17;border:1px solid #1c352d;border-radius:5px}.guide-title{font:9px 'DM Mono',monospace;text-transform:uppercase;letter-spacing:.12em;color:#bca16b;margin-bottom:8px}.guide p{color:#96a79d;font-size:9px;line-height:1.55;margin:0}.guide strong{color:#d5ddcf;font-weight:600}.bottomline{display:flex;justify-content:space-between;color:#60786c;font:9px 'DM Mono',monospace;margin:24px 8px 0}.modal-backdrop{position:fixed;inset:0;background:#06110fe6;display:grid;place-items:center;padding:20px;z-index:10}.modal{width:min(440px,100%);padding:30px;border:1px solid #526348;border-radius:10px;background:linear-gradient(145deg,#17382f,#0e211c);text-align:center;box-shadow:0 24px 70px #000b}.modal h2{font:600 27px 'Playfair Display',serif;margin:7px 0 9px}.modal p{color:#a7b6aa;font-size:12px;line-height:1.65}.modal .action-btn{margin-top:12px}.hidden{display:none!important}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
@media(max-width:850px){.shell{padding:18px 20px 24px}.layout{grid-template-columns:1fr}.sidebar{min-height:auto;display:grid;grid-template-columns:1fr 1fr;gap:0 18px}.sidebar>.side-title:first-child{grid-column:1/-1}.stat-grid{grid-column:1/-1}.divider{grid-column:1/-1}.history-head,.history,.empty-history{grid-column:1}.guide{grid-column:2;grid-row:3 / span 2;margin-top:0}.poker-table{height:435px}.bottomline{margin-top:17px}}
@media(max-width:560px){.shell{padding:14px 12px 20px}.topbar{margin-bottom:20px}.brand-name{font-size:15px}.pill{font-size:9px;padding:7px 9px}.layout{gap:16px}.table-head{margin:0 4px 10px}.eyebrow{font-size:8px}h1{font-size:21px}.table-meta{font-size:8px}.poker-table{height:390px;border-radius:45% / 44%;box-shadow:inset 0 0 0 5px #18352d,inset 0 0 0 7px #52724e,0 14px 35px #0008}.poker-table:before{inset:17px}.seat{min-width:94px}.seat[data-seat="1"]{left:-1%}.seat[data-seat="3"]{right:-1%}.player-info{gap:5px;padding:5px 8px 5px 5px}.avatar{width:25px;height:25px;font-size:10px}.player-name{font-size:9px}.player-stack{font-size:8px}.playing-card{width:29px;height:41px;font-size:13px}.hole-cards{min-height:43px;gap:3px;margin-top:5px}.community{gap:5px;top:48%}.community .playing-card{width:39px;height:55px;font-size:17px}.community .playing-card .corner{font-size:8px;line-height:9px}.pot-box{top:29%}.pot-value{font-size:16px}.stage-badge{top:71%;font-size:8px}.notice{top:82%;font-size:9px;max-width:80%;white-space:normal}.table-ornament{font-size:8px;top:18%}.action-bar{margin-top:38px;gap:6px}.action-btn{height:40px;min-width:0;padding:0 12px;flex:1;font-size:10px}.raise-wrap{flex:1}.raise-wrap .action-btn{min-width:0;width:100%;padding:0 8px}.hint{font-size:9px}.sidebar{padding:13px 11px;grid-template-columns:1fr}.sidebar>.side-title:first-child,.stat-grid,.divider,.history-head,.history,.empty-history,.guide{grid-column:1}.guide{grid-row:auto;margin-top:14px}.stat{padding:8px}.bottomline{font-size:8px;margin:17px 2px 0}}
</style>
</head>
<body>
<div class="shell">
<header class="topbar"><div class="brand"><div class="brand-icon">♠</div><div><div class="brand-name">The River Room</div><span class="brand-sub">Private table · est. 2024</span></div></div><div class="top-actions"><div class="pill"><span>●</span> Practice table</div><button class="icon-btn" id="sound-toggle" aria-label="Toggle sound" title="Toggle sound">♪</button></div></header>
<main class="layout">
<section class="game-column" aria-label="Poker game">
<div class="table-head"><div><div class="eyebrow">No-limit Texas hold’em</div><h1>Friday Night Cash</h1></div><div class="table-meta">BLINDS&nbsp; 10 / 20</div></div>
<div class="poker-table" id="poker-table" aria-label="Poker table">
<div class="table-ornament">♣ &nbsp; RIVER ROOM &nbsp; ♣</div><div class="seats" id="seats"></div>
<div class="pot-box"><div class="pot-label">Total pot</div><div class="pot-value" id="pot">$0</div></div>
<div class="community" id="community" aria-label="Community cards"></div>
<div class="stage-badge" id="stage">Waiting for next hand</div>
<div class="notice" id="notice">Your seat is ready.</div>
</div>
<div class="action-bar" id="actions"><button class="action-btn fold" id="fold">Fold</button><button class="action-btn" id="check-call">Check</button><div class="raise-wrap"><button class="action-btn primary" id="raise">Raise $40</button></div></div>
<div class="hint" id="hint" aria-live="polite">Your move when the gold ring reaches your seat.</div>
</section>
<aside class="sidebar" aria-label="Table information">
<div class="side-title">Your session</div><div class="stat-grid"><div class="stat"><div class="stat-label">Your balance</div><div class="stat-value" id="balance">$1,000</div></div><div class="stat"><div class="stat-label">Hands played</div><div class="stat-value" id="hands-played">01</div></div><div class="stat"><div class="stat-label">Hands won</div><div class="stat-value" id="hands-won">00</div></div><div class="stat"><div class="stat-label">Big blind</div><div class="stat-value">$20</div></div></div>
<div class="divider"></div><div class="history-head"><div class="side-title" style="margin:0">Recent hands</div><button id="clear-history">Clear</button></div><div class="history" id="history"><div class="empty-history">The cards are in your hands. Your results will show up here.</div></div>
<div class="guide"><div class="guide-title">Quick rules</div><p>Make the best <strong>five-card hand</strong> from your two hole cards and five shared cards. Check, call, raise, or fold when it’s your turn. The strongest hand takes the pot.</p></div>
</aside>
</main>
<footer class="bottomline"><span>PLAY FOR FUN · NO REAL MONEY</span><span id="hand-label">HAND 01&nbsp; / &nbsp;DEALING</span></footer>
</div>
<div class="modal-backdrop hidden" id="result-modal"><div class="modal"><div class="eyebrow" id="result-kicker">Hand complete</div><h2 id="result-title">You take the pot.</h2><p id="result-copy"></p><button class="action-btn primary" id="next-hand">Deal next hand</button></div></div>
<script>
(() => {
const SUITS=[{s:'♠',c:'black'},{s:'♥',c:'red'},{s:'♦',c:'red'},{s:'♣',c:'black'}],RANKS='23456789TJQKA';
const names=['You','Mara','Theo','Jules'],faces=['Y','M','T','J'];
let players=names.map((name,i)=>({name,face:faces[i],stack:1000,folded:false,allIn:false,street:0,hand:[]}));
let handNo=0,wins=0,dealer=0,deck=[],board=[],pot=0,currentBet=0,acted=new Set(),actor=-1,stage='idle',busy=false,handOver=true,history=[];
const $=id=>document.getElementById(id),seatRoot=$('seats');
const money=n=>'$'+Math.max(0,Math.round(n)).toLocaleString('en-US');
function makeDeck(){deck=[];for(const suit of SUITS)for(let i=0;i<RANKS.length;i++)deck.push({r:RANKS[i],v:i+2,s:suit.s,c:suit.c});for(let i=deck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]]}}
function draw(){return deck.pop()}
function cardHTML(c,back=false){return back?'<div class="playing-card back">♠</div>':`<div class="playing-card ${c.c}"><span class="corner">${c.r==='T'?'10':c.r}${c.s}</span>${c.s}</div>`}
function render(){
 seatRoot.innerHTML=players.map((p,i)=>{const seat=(i-dealer+4)%4;const shown=p.hand.length&&(i===0||(stage==='showdown'&&!p.folded));const cards=p.hand.length?(i===0||shown?p.hand.map(c=>cardHTML(c)).join(''):cardHTML(null,true)+cardHTML(null,true)):'';return `<div class="seat ${p.folded?'folded':''} ${actor===i&&!handOver?'active':''} ${p.winner?'winner':''}" data-seat="${seat}"><div class="player-info"><div class="avatar">${p.face}</div><div><div class="player-name">${p.name}</div><div class="player-stack">${money(p.stack)}</div></div></div>${i===dealer?'<div class="dealer-chip">D</div>':''}<div class="hole-cards">${cards}</div><div class="status-tag">${p.status||''}</div></div>`}).join('');
 $('pot').textContent=money(pot);$('community').innerHTML=Array.from({length:5},(_,i)=>board[i]?cardHTML(board[i]):'<div class="playing-card" style="opacity:.13;background:#d9ddc9"></div>').join('');
 $('stage').textContent=stage==='idle'?'Ready to play':stage==='preflop'?'Pre-flop':stage==='flop'?'The flop':stage==='turn'?'The turn':stage==='river'?'The river':'Showdown';
 $('notice').textContent=message;$('balance').textContent=money(players[0].stack);$('hands-played').textContent=String(Math.max(1,handNo)).padStart(2,'0');$('hands-won').textContent=String(wins).padStart(2,'0');$('hand-label').textContent=`HAND ${String(Math.max(1,handNo)).padStart(2,'0')}  /  ${stage==='idle'?'READY':stage.toUpperCase()}`;
 const isTurn=actor===0&&!handOver&&!busy,owe=Math.max(0,currentBet-players[0].street);
 $('fold').disabled=!isTurn;$('check-call').disabled=!isTurn;$('raise').disabled=!isTurn||players[0].stack<=owe+10;
 $('check-call').textContent=owe?`Call ${money(Math.min(owe,players[0].stack))}`:'Check';$('raise').textContent=`Raise ${money(Math.max(40,currentBet||20))}`;
 $('hint').textContent=handOver?'Deal a hand and see where the cards take you.':isTurn?(owe?`It’s ${money(owe)} to you. Choose your action.`:'No bet to call. Check or make it interesting.'):'The table is playing…';
 $('actions').classList.toggle('hidden',handOver&&stage!=='idle');
}
let message='Your seat is ready.';
function updateAction(i,text){players[i].status=text;setTimeout(()=>{if(players[i].status===text){players[i].status='';render()}},1100)}
function post(i,amount){const paid=Math.min(amount,players[i].stack);players[i].stack-=paid;players[i].street+=paid;pot+=paid;if(players[i].stack===0)players[i].allIn=true;return paid}
function active(){return players.map((p,i)=>!p.folded?i:-1).filter(i=>i>=0)}
function eligible(){return players.map((p,i)=>!p.folded&&!p.allIn?i:-1).filter(i=>i>=0)}
function afterAction(){if(active().length===1){const winner=active()[0];players[winner].stack+=pot;const won=pot;players[winner].winner=true;message=`${players[winner].name} wins ${money(won)} — everyone else folded.`;finishHand([players[winner].name],`Won by fold`,`${players[winner].name} takes the pot uncontested.`,winner===0);return}
 const need=eligible();if(need.every(i=>acted.has(i)&&players[i].street===currentBet)){if(need.length<=1){while(board.length<5)board.push(draw());render();setTimeout(showdown,650)}else advanceStreet();return}
 actor=nextActor(actor);if(actor<0){advanceStreet();return}if(actor===0){busy=false;render()}else{busy=true;render();setTimeout(()=>botAction(actor),620+Math.random()*580)}}
function nextActor(from){for(let step=1;step<=4;step++){const i=(from+step)%4;if(!players[i].folded&&!players[i].allIn&&(!acted.has(i)||players[i].street<currentBet))return i}return -1}
function takeAction(i,kind){if(handOver||i!==actor)return;const p=players[i],owe=Math.max(0,currentBet-p.street);p.status='';
 if(kind==='fold'){p.folded=true;acted.add(i);updateAction(i,'Folded');message=`${p.name} folds.`}
 else if(kind==='check'||kind==='call'){const paid=post(i,kind==='call'?owe:0);acted.add(i);updateAction(i,paid?`Calls ${money(paid)}`:'Checks');message=paid?`${p.name} calls ${money(paid)}.`:`${p.name} checks.`}
 else if(kind==='raise'){const target=currentBet+40,cost=target-p.street;if(cost>p.stack){message='Not enough chips to make that raise.';busy=false;render();return}post(i,cost);currentBet=target;acted=new Set([i]);updateAction(i,`Raises to ${money(target)}`);message=`${p.name} raises to ${money(target)}.`}
 afterAction()}
function botAction(i){if(handOver||actor!==i)return;const p=players[i],owe=Math.max(0,currentBet-p.street),strength=(p.hand[0].v+p.hand[1].v)/2+Math.random()*7;let action='call';if(owe===0)action=strength>11&&Math.random()<.23?'raise':'check';else if(owe>=p.stack||owe>100)action=strength<9&&Math.random()<.5?'fold':'call';else if(strength<6.4&&Math.random()<.36)action='fold';else if(strength>11.8&&Math.random()<.16&&p.stack>owe+40)action='raise';takeAction(i,action)}
function advanceStreet(){if(handOver)return;players.forEach(p=>{p.street=0;p.status=''});currentBet=0;acted=new Set();actor=-1;if(stage==='preflop'){stage='flop';board.push(draw(),draw(),draw())}else if(stage==='flop'){stage='turn';board.push(draw())}else if(stage==='turn'){stage='river';board.push(draw())}else{showdown();return}message=stage==='flop'?'The flop is out.':stage==='turn'?'Fourth street — the turn.':'Fifth street — the river.';actor=nextActor(dealer);if(active().length<=1||eligible().length<=1){while(board.length<5)board.push(draw());setTimeout(showdown,650);render();return}if(actor===0){busy=false;render()}else{busy=true;render();setTimeout(()=>botAction(actor),650)}}
function startHand(){if(busy)return;if(players[0].stack<10){$('result-kicker').textContent='Seat empty';$('result-title').textContent='Ready for another round?';$('result-copy').textContent='Your chips ran out. Rebuy a fresh practice stack to keep playing.';$('next-hand').textContent='Rebuy $1,000';$('result-modal').classList.remove('hidden');return}
 handNo++;handOver=false;busy=false;stage='preflop';message='Cards dealt. Let’s play.';board=[];pot=0;currentBet=0;acted=new Set();players.forEach(p=>{p.folded=p.stack<=0;p.allIn=false;p.street=0;p.hand=[];p.status='';p.winner=false;p.reveal=false});makeDeck();players.forEach(p=>{if(!p.folded)p.hand=[draw(),draw()]});dealer=(handNo-1)%4;const sb=(dealer+1)%4,bb=(dealer+2)%4;post(sb,10);post(bb,20);players[sb].status='Small blind';players[bb].status='Big blind';currentBet=Math.max(players[sb].street,players[bb].street);actor=(bb+1)%4;actor=nextActor((actor+3)%4); // first active player clockwise after big blind
 if(actor<0)actor=0;render();if(actor!==0){busy=true;setTimeout(()=>botAction(actor),650)}}
function scoreFive(cards){const counts={};cards.forEach(c=>counts[c.v]=(counts[c.v]||0)+1);const groups=Object.entries(counts).map(([v,n])=>({v:+v,n})).sort((a,b)=>b.n-a.n||b.v-a.v);const flush=cards.every(c=>c.s===cards[0].s);const vals=[...new Set(cards.map(c=>c.v))].sort((a,b)=>b-a);let straight=0;for(let i=0;i<=vals.length-5;i++)if(vals[i]-vals[i+4]===4){straight=vals[i];break}if(!straight&&vals.includes(14)&&[2,3,4,5].every(v=>vals.includes(v)))straight=5;
 if(flush&&straight)return[8,straight];if(groups[0].n===4)return[7,groups[0].v,groups[1].v];if(groups[0].n===3&&groups[1].n===2)return[6,groups[0].v,groups[1].v];if(flush)return[5,...vals];if(straight)return[4,straight];if(groups[0].n===3)return[3,groups[0].v,...groups.slice(1).map(g=>g.v).sort((a,b)=>b-a)];if(groups[0].n===2&&groups[1].n===2)return[2,Math.max(groups[0].v,groups[1].v),Math.min(groups[0].v,groups[1].v),groups[2].v];if(groups[0].n===2)return[1,groups[0].v,...groups.slice(1).map(g=>g.v).sort((a,b)=>b-a)];return[0,...vals]}
function bestHand(cards){let best=null;for(let a=0;a<cards.length-4;a++)for(let b=a+1;b<cards.length-3;b++)for(let c=b+1;c<cards.length-2;c++)for(let d=c+1;d<cards.length-1;d++)for(let e=d+1;e<cards.length;e++){const sc=scoreFive([cards[a],cards[b],cards[c],cards[d],cards[e]]);if(!best||compare(sc,best)>0)best=sc}return best}
function compare(a,b){for(let i=0;i<Math.max(a.length,b.length);i++){const d=(a[i]||0)-(b[i]||0);if(d)return d}return 0}
const handNames=['High card','One pair','Two pair','Three of a kind','Straight','Flush','Full house','Four of a kind','Straight flush'];
function showdown(){if(handOver)return;stage='showdown';players.forEach(p=>{p.status='';p.reveal=!p.folded});const remaining=active(),scored=remaining.map(i=>({i,score:bestHand([...players[i].hand,...board])})).sort((a,b)=>compare(b.score,a.score));const winners=scored.filter(x=>compare(x.score,scored[0].score)===0).map(x=>x.i);const label=handNames[scored[0].score[0]];players.forEach(p=>p.winner=false);winners.forEach(i=>players[i].winner=true);const part=Math.floor(pot/winners.length);winners.forEach(i=>players[i].stack+=part);if(pot%winners.length)players[winners[0]].stack+=pot%winners.length;const lead=winners[0]===0;message=winners.length>1?`Split pot — ${winners.map(i=>players[i].name).join(' & ')}.`:`${players[winners[0]].name} wins with ${label}.`;finishHand(winners.map(i=>players[i].name).join(' & '),label,`${winners.map(i=>players[i].name).join(' and ')} ${winners.length>1?'split':'win'} ${money(pot)} with ${label.toLowerCase()}.`,lead)}
function finishHand(winners,label,copy,heroWon=false){handOver=true;busy=false;actor=-1;if(heroWon)wins++;players.forEach(p=>p.status=p.winner?'Winner':'');history.unshift({hand:handNo,winners,label,pot});history=history.slice(0,5);renderHistory();render();$('result-kicker').textContent=heroWon?'Nice hand':'Hand complete';$('result-title').textContent=heroWon?'You take the pot.':(winners.includes('You')?'You split the pot.':`${winners.split(' & ')[0]} takes it.`);$('result-copy').textContent=copy;$('next-hand').textContent=players[0].stack<10?'Rebuy $1,000':'Deal next hand';$('result-modal').classList.remove('hidden')}
function renderHistory(){$('history').innerHTML=history.length?history.map(h=>`<div class="history-item"><span class="history-dot"></span><div><strong>Hand ${String(h.hand).padStart(2,'0')}</strong> · ${h.winners}<small>${h.label} · ${money(h.pot)} pot</small></div></div>`).join(''):'<div class="empty-history">The cards are in your hands. Your results will show up here.</div>'}
$('fold').addEventListener('click',()=>takeAction(0,'fold'));$('check-call').addEventListener('click',()=>takeAction(0,players[0].street<currentBet?'call':'check'));$('raise').addEventListener('click',()=>takeAction(0,'raise'));
$('next-hand').addEventListener('click',()=>{$('result-modal').classList.add('hidden');if(players[0].stack<10)players[0].stack=1000;startHand()});$('clear-history').addEventListener('click',()=>{history=[];renderHistory()});$('sound-toggle').addEventListener('click',e=>{e.currentTarget.classList.toggle('primary');e.currentTarget.title=e.currentTarget.classList.contains('primary')?'Sound on':'Sound off'});
render();renderHistory();startHand();
})();
</script>
</body>
