if [[ ! -f "$STATIC_DIR/index.html" ]]; then
  echo "Static directory is missing index.html: $STATIC_DIR" >&2
  exit 1
fi
run mkdir -p "${OPENCODE_WEB_DIR:?OPENCODE_WEB_DIR must be set}"
run node -e 'const fs=require("node:fs");const p=process.argv[1],d=process.argv[2];fs.writeFileSync(p,JSON.stringify({project:d,directory:fs.realpathSync(process.argv[3])}))' "$OPENCODE_WEB_DIR/deployment-output.json" "$PROJECT_DIR" "$STATIC_DIR"

exec /usr/bin/time -p node --input-type=module - "$STATIC_DIR" "$PORT" <<'SERVER'
import { createServer } from 'node:http';
import { readFile, stat } from 'node:fs/promises';
import { resolve, extname, join } from 'node:path';
const root=resolve(process.argv[2]),port=Number(process.argv[3]);
const types={'.html':'text/html; charset=utf-8','.css':'text/css; charset=utf-8','.js':'application/javascript; charset=utf-8','.json':'application/json','.svg':'image/svg+xml','.png':'image/png','.jpg':'image/jpeg'};
const server=createServer(async(req,res)=>{try{const url=new URL(req.url,'http://localhost');let file=resolve(root,'.'+decodeURIComponent(url.pathname));if(file!==root&&!file.startsWith(root+'/')){res.writeHead(403);res.end('Forbidden');return}if((await stat(file)).isDirectory())file=join(file,'index.html');const body=await readFile(file);res.writeHead(200,{'Content-Type':types[extname(file)]||'application/octet-stream','Cache-Control':'no-store'});res.end(body)}catch{res.writeHead(404,{'Content-Type':'text/plain'});res.end('Not found')}});
server.listen(port,'0.0.0.0',()=>console.log(`Poker table serving ${root} on port ${port}`));
for(const signal of ['SIGINT','SIGTERM'])process.on(signal,()=>server.close(()=>process.exit(0)));
